"use client";
import { Form } from "@/components/ui/form";
import React, { useState } from "react";
import type {
  DefaultValues,
  FormState,
  UseFormReturn,
} from "react-hook-form";
import { useForm } from "react-hook-form";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { zodResolver } from "@hookform/resolvers/zod";

import AutoFormObject from "./fields/object";
import type { Dependency, FieldConfig } from "./types";
import type { ZodObjectOrWrapped } from "./helpers";
import { getDefaultValues, getObjectFormSchema } from "./helpers";

export function AutoFormSubmit({
  children,
  className,
  disabled,
}: {
  children?: React.ReactNode;
  className?: string;
  disabled?: boolean;
}) {
  return (
    <Button type="submit" disabled={disabled} className={className}>
      {children ?? "Submit"}
    </Button>
  );
}

function AutoForm<SchemaType extends ZodObjectOrWrapped>({
  formSchema,
  values: valuesProp,
  onValuesChange: onValuesChangeProp,
  onParsedValuesChange,
  onSubmit: onSubmitProp,
  fieldConfig,
  children,
  className,
  dependencies,
}: {
  formSchema: SchemaType;
  values?: Partial<z.infer<SchemaType>>;
  onValuesChange?: (
    values: Partial<z.infer<SchemaType>>,
    form: UseFormReturn<z.infer<SchemaType>>
  ) => void;
  onParsedValuesChange?: (
    values: Partial<z.infer<SchemaType>>,
    form: UseFormReturn<z.infer<SchemaType>>
  ) => void;
  onSubmit?: (
    values: z.infer<SchemaType>,
    form: UseFormReturn<z.infer<SchemaType>>
  ) => void;
  fieldConfig?: FieldConfig<z.infer<SchemaType>>;
  children?:
    | React.ReactNode
    | ((formState: FormState<z.infer<SchemaType>>) => React.ReactNode);
  className?: string;
  dependencies?: Dependency<z.infer<SchemaType>>[];
}) {
  const objectFormSchema = getObjectFormSchema(formSchema);
  const defaultValues: DefaultValues<z.infer<typeof objectFormSchema>> | null =
    getDefaultValues(objectFormSchema, fieldConfig);

  const form = useForm<Record<string, unknown>>({
    // Cast to any to handle Zod v4 type compatibility with @hookform/resolvers
    resolver: zodResolver(formSchema as any) as any,
    defaultValues: (defaultValues ?? undefined) as any,
    values: valuesProp as any,
  });

  const [schemaSubmitError, setSchemaSubmitError] = useState<string | null>(null);

  function onSubmit(values: Record<string, unknown>) {
    setSchemaSubmitError(null);
    const parsedValues = formSchema.safeParse(values);
    if (parsedValues.success) {
      onSubmitProp?.(parsedValues.data as z.infer<SchemaType>, form as any);
    } else {
      const message = parsedValues.error.issues
        .map(
          (issue) =>
            `${issue.path.length ? `${issue.path.join(".")}: ` : ""}${issue.message}`,
        )
        .join(" · ");
      setSchemaSubmitError(message);
    }
  }

  React.useEffect(() => {
    const subscription = form.watch((values) => {
      onValuesChangeProp?.(values as any, form as any);
      const parsedValues = formSchema.safeParse(values);
      if (parsedValues.success) {
        onParsedValuesChange?.(parsedValues.data as any, form as any);
      }
    });

    return () => subscription.unsubscribe();
  }, [form, formSchema, onValuesChangeProp, onParsedValuesChange]);

  const renderChildren =
    typeof children === "function"
      ? children(form.formState as FormState<z.infer<SchemaType>>)
      : children;

  return (
    <div className="w-full">
      <Form {...form}>
        <form
          onSubmit={(e) => {
            form.handleSubmit(onSubmit, () => setSchemaSubmitError(null))(e);
          }}
          className={cn("space-y-5", className)}
        >
          <AutoFormObject
            schema={objectFormSchema}
            form={form as any}
            dependencies={dependencies as any}
            fieldConfig={fieldConfig as any}
          />

          {schemaSubmitError ? (
            <div
              role="alert"
              className="rounded-md border border-destructive/50 bg-destructive/10 p-3 text-sm text-destructive"
            >
              {schemaSubmitError}
            </div>
          ) : null}

          {renderChildren}
        </form>
      </Form>
    </div>
  );
}

export default AutoForm;

/**
 * Shared types between form-builder and auto-form.
 * 
 * These types ensure consistency when:
 * - form-builder creates JSON Schema properties
 * - auto-form consumes JSON Schema properties
 * - inputProps flow from form-builder → JSON Schema → auto-form
 */

import type { INPUT_COMPONENTS } from "./config";

// ============================================================================
// INPUT PROPS BY BACKING TYPE
// ============================================================================

/**
 * Common input props shared by all field types.
 */
export interface BaseInputProps {
  /** Whether the field is disabled */
  disabled?: boolean;
  /** Whether the field is read-only */
  readOnly?: boolean;
  /** Whether the field is required */
  required?: boolean;
  /** Whether to show the label (auto-form specific) */
  showLabel?: boolean;
}

/**
 * Input props for string-backed fields (text, email, password, url, phone, textarea).
 */
export interface StringInputProps extends BaseInputProps {
  /** Placeholder text */
  placeholder?: string;
  /** HTML input type (text, email, password, tel, url) */
  type?: "text" | "email" | "password" | "tel" | "url" | string;
  /** Default value */
  defaultValue?: string;
  /** Minimum length */
  minLength?: number;
  /** Maximum length */
  maxLength?: number;
  /** Regex pattern for validation */
  pattern?: string;
  /** Autocomplete hint */
  autoComplete?: string;
}

/**
 * Input props for number-backed fields.
 */
export interface NumberInputProps extends BaseInputProps {
  /** Placeholder text */
  placeholder?: string;
  /** Default value */
  defaultValue?: number;
  /** Minimum value */
  min?: number;
  /** Maximum value */
  max?: number;
  /** Step value for increment/decrement */
  step?: number;
}

/**
 * Input props for boolean-backed fields (checkbox, switch).
 */
export interface BooleanInputProps extends BaseInputProps {
  /** Default value */
  defaultValue?: boolean;
}

/**
 * Input props for date-backed fields.
 */
export interface DateInputProps extends BaseInputProps {
  /** Default value as ISO string or Date */
  defaultValue?: string | Date;
  /** Minimum date as ISO string */
  min?: string;
  /** Maximum date as ISO string */
  max?: string;
}

/**
 * Input props for enum-backed fields (select, radio).
 */
export interface EnumInputProps extends BaseInputProps {
  /** Placeholder text (for select) */
  placeholder?: string;
  /** Default value (must match one of the enum options) */
  defaultValue?: string;
}

/**
 * Union type of all input props by backing type.
 */
export type TypedInputProps = 
  | StringInputProps
  | NumberInputProps
  | BooleanInputProps
  | DateInputProps
  | EnumInputProps;

/**
 * Generic input props that accept any field type.
 * Use this when the backing type is not known at compile time.
 * 
 * This is the catch-all type used for runtime flexibility.
 */
export interface SerializableInputProps extends BaseInputProps {
  placeholder?: string;
  type?: string;
  defaultValue?: unknown;
  min?: number | string;
  max?: number | string;
  step?: number | string;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  autoComplete?: string;
  /** Allow additional props for extensibility */
  [key: string]: unknown;
}

// ============================================================================
// INPUT PROPS TYPE MAPPING
// ============================================================================

/**
 * Maps backing Zod types to their corresponding input props type.
 */
export interface InputPropsByBackingType {
  string: StringInputProps;
  number: NumberInputProps;
  boolean: BooleanInputProps;
  date: DateInputProps;
  enum: EnumInputProps;
}

/**
 * Get the correct input props type for a backing type.
 */
export type InputPropsFor<T extends keyof InputPropsByBackingType> = InputPropsByBackingType[T];

/**
 * Built-in field types supported by auto-form.
 */
export type AutoFormBuiltinFieldType = keyof typeof INPUT_COMPONENTS;

/**
 * Field types that can be specified in JSON Schema.
 * Either a built-in type name or a custom component.
 */
export type FieldType = 
  | AutoFormBuiltinFieldType
  | (string & {});  // allow any string for extensibility

/**
 * JSON Schema property with form-builder and auto-form metadata.
 * 
 * This is the intermediate format used when:
 * - form-builder serializes field configurations
 * - auto-form parses JSON Schema to build field configs
 */
export interface JSONSchemaPropertyBase {
  // ========================
  // Standard JSON Schema
  // ========================
  /** JSON Schema type */
  type?: "string" | "number" | "integer" | "boolean" | "object" | "array" | "null";
  /** Human-readable title (JSON Schema standard) */
  title?: string;
  /** Description text */
  description?: string;
  /** Default value */
  default?: unknown;
  /** Enum values for select/radio fields */
  enum?: (string | number | boolean | null)[];
  /** Minimum value for numbers */
  minimum?: number;
  /** Maximum value for numbers */
  maximum?: number;
  /** Exclusive minimum for numbers */
  exclusiveMinimum?: number;
  /** Exclusive maximum for numbers */
  exclusiveMaximum?: number;
  /** Minimum length for strings */
  minLength?: number;
  /** Maximum length for strings */
  maxLength?: number;
  /** Regex pattern for strings */
  pattern?: string;
  /** Format hint (email, uri, date-time, etc.) */
  format?: string;
  /** Multiple of constraint for numbers */
  multipleOf?: number;

  // ========================
  // Nested structures
  // ========================
  /** Properties for object types */
  properties?: Record<string, JSONSchemaPropertyBase>;
  /** Required fields for object types */
  required?: string[];
  /** Additional properties allowed for objects */
  additionalProperties?: boolean;
  /** Item schema for array types */
  items?: JSONSchemaPropertyBase;

  // ========================
  // Form metadata (via Zod .meta())
  // ========================
  /** Display label (form-builder/auto-form) */
  label?: string;
  /** Field type override (checkbox, date, select, radio, switch, textarea, etc.) */
  fieldType?: FieldType;
  /** Placeholder text */
  placeholder?: string;
  /** HTML input type (text, email, password, tel, etc.) */
  inputType?: string;
  /** Additional input props */
  inputProps?: SerializableInputProps;
  /** Display order */
  order?: number;

  // ========================
  // Date constraints (from zodToFormSchema)
  // ========================
  /** Minimum date as ISO string */
  formatMinimum?: string;
  /** Maximum date as ISO string */
  formatMaximum?: string;
}

/**
 * Field configuration item that auto-form uses to customize field rendering.
 * This is the target type when converting from JSON Schema.
 * 
 * Note: This is kept in sync with auto-form/types.ts FieldConfigItem
 */
export interface FieldConfigItemBase {
  /** Description text or React node */
  description?: React.ReactNode;
  /** Input props passed to the field component */
  inputProps?: SerializableInputProps;
  /** Display label */
  label?: string;
  /** Field type override */
  fieldType?: FieldType | React.ComponentType<unknown>;
  /** Wrapper component */
  renderParent?: (props: { children: React.ReactNode }) => React.ReactElement | null;
  /** Display order */
  order?: number;
}

/**
 * Mapping of JSON Schema property keys to FieldConfigItem keys.
 * Used when converting between formats.
 */
export const JSON_SCHEMA_TO_FIELD_CONFIG_MAP = {
  // Direct mappings
  label: "label",
  description: "description",
  fieldType: "fieldType",
  inputProps: "inputProps",
  order: "order",
  // Properties that go into inputProps
  placeholder: "inputProps.placeholder",
  inputType: "inputProps.type",
  default: "inputProps.defaultValue",
} as const;

import type { ControllerRenderProps, FieldValues } from "react-hook-form";
import * as z from "zod";
import { INPUT_COMPONENTS } from "./config";
import type { 
  SerializableInputProps,
  StringInputProps,
  NumberInputProps,
  BooleanInputProps,
  DateInputProps,
  EnumInputProps,
  TypedInputProps,
} from "./shared-form-types";

// Re-export discriminated input prop types for field components
export type {
  SerializableInputProps,
  StringInputProps,
  NumberInputProps,
  BooleanInputProps,
  DateInputProps,
  EnumInputProps,
  TypedInputProps,
};

/**
 * Available field types for AutoForm fieldConfig.
 * These map to the input components in ./config.ts
 */
export type AutoFormFieldType = keyof typeof INPUT_COMPONENTS;

/**
 * Input props for form fields.
 * 
 * This is the runtime type that accepts any input props.
 * For type-safe props, use the discriminated types:
 * - StringInputProps for text inputs
 * - NumberInputProps for number inputs
 * - BooleanInputProps for checkboxes/switches
 * - DateInputProps for date pickers
 * - EnumInputProps for selects/radios
 */
export type FieldInputProps = SerializableInputProps & 
  Omit<React.InputHTMLAttributes<HTMLInputElement>, keyof SerializableInputProps> &
  Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, keyof SerializableInputProps>;

/**
 * Configuration for a single field in AutoForm.
 * 
 * Note: This type is designed to align with form-builder's FormBuilderFieldProps
 * so that JSON Schema properties can be easily converted to field configs.
 */
export type FieldConfigItem = {
  /** Description text or React node */
  description?: React.ReactNode;
  /** Input props passed to the field component */
  inputProps?: FieldInputProps;
  /** Display label */
  label?: string;
  /** Field type override - built-in type or custom component */
  fieldType?:
    | keyof typeof INPUT_COMPONENTS
    | React.FC<AutoFormInputComponentProps>;
  /** Wrapper component for custom field layout */
  renderParent?: (props: {
    children: React.ReactNode;
  }) => React.ReactElement | null;
  /** Display order for field ordering */
  order?: number;
};

/**
 * FieldConfig for nested objects - allows both FieldConfigItem properties
 * AND nested field configs for child properties.
 */
export type FieldConfigObject = FieldConfigItem & {
  [key: string]: FieldConfigItem | FieldConfigObject | undefined;
};

/**
 * For object fields, allow both FieldConfigItem properties (label, description, etc.)
 * AND nested field configs for the object's properties.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Required for Zod generic inference
export type FieldConfig<SchemaType extends z.infer<z.ZodObject<any, any>>> = {
  [Key in keyof SchemaType]?: FieldConfigItem | FieldConfigObject;
};

export enum DependencyType {
  DISABLES,
  REQUIRES,
  HIDES,
  SETS_OPTIONS,
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Required for Zod generic inference
type BaseDependency<SchemaType extends z.infer<z.ZodObject<any, any>>> = {
  sourceField: keyof SchemaType;
  type: DependencyType;
  targetField: keyof SchemaType;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Dynamic field value types
  when: (sourceFieldValue: any, targetFieldValue: any) => boolean;
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Required for Zod generic inference
export type ValueDependency<SchemaType extends z.infer<z.ZodObject<any, any>>> =
  BaseDependency<SchemaType> & {
    type:
      | DependencyType.DISABLES
      | DependencyType.REQUIRES
      | DependencyType.HIDES;
  };

export type EnumValues = readonly [string, ...string[]];

export type OptionsDependency<
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Required for Zod generic inference
  SchemaType extends z.infer<z.ZodObject<any, any>>,
> = BaseDependency<SchemaType> & {
  type: DependencyType.SETS_OPTIONS;

  // Partial array of values from sourceField that will trigger the dependency
  options: EnumValues;
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Required for Zod generic inference
export type Dependency<SchemaType extends z.infer<z.ZodObject<any, any>>> =
  | ValueDependency<SchemaType>
  | OptionsDependency<SchemaType>;

/**
 * A FormInput component can handle a specific Zod type (e.g. "ZodBoolean")
 */
export type AutoFormInputComponentProps = {
  zodInputProps: React.InputHTMLAttributes<HTMLInputElement>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- react-hook-form field name type
  field: ControllerRenderProps<FieldValues, any>;
  fieldConfigItem: FieldConfigItem;
  label: string;
  isRequired: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Dynamic field props from Zod schema
  fieldProps: any;
  zodItem: z.ZodType;
  className?: string;
};
